    evt.SetLight(40001, 1)
    evt.SetLight(40002, 1)
    evt.SetLight(40003, 1)
    evt.CameraShake(0.4, 0.8); evt.PlaySoundName("xeen_gong", 4912, 3640, 52)
    evt.StatusText("BOOM! The great gong rolls through the hold. Doors crash open in the barracks.", 6)
end, "The great gong")

